from __future__ import annotations

from typing import cast

from vsniper.domain.contracts import (
    CLOTHING_ITEM_DESCRIPTIONS,
    CLOTHING_ITEM_LABELS,
    ClothingItem,
    SearchFilter,
)
from vsniper.integrations.vinted.category_aliases import CATEGORY_ALIAS_IDS


_CATEGORY_FIELDS = {"category", "catalog"}

# The only Vinted catalogs each bucket searches: (catalog ID, Vinted.de title) from the Herren
# catalog tree, read from the live site on 2026-11-07. A parent catalog includes its children,
# and no catalog belongs to two buckets. Categories are fixed here, never generated by a taste
# recompute or edited per search.
#
#   warm    Tops & T-Shirts (T-shirts, shirts, polos, tank tops)
#   mittel  light pullovers and hoodies from Pullover & Sweater
#   kalt    winter knits and cardigans from Pullover & Sweater, plus all Jacken & Mäntel
FIXED_CATEGORIES_BY_ITEM: dict[ClothingItem, list[tuple[str, str]]] = {
    "schuhe": [("1242", "Sneaker"), ("1233", "Stiefel")],
    "hosen": [("34", "Hosen"), ("257", "Jeans")],
    "obenrum_warm": [("76", "Tops & T-Shirts")],
    "obenrum_mittel": [
        ("1811", "Sweater"),
        ("267", "Pullis & Hoodies"),
        ("1812", "Kapuzenjacken"),
        ("1813", "Pullover mit Rundhalsausschnitt"),
        ("264", "Pullover mit V-Ausschnitt"),
        ("265", "Rollkragenpullover"),
        ("1814", "Lange Pullover"),
    ],
    "obenrum_kalt": [
        ("1815", "Strickpullover für den Winter"),
        ("266", "Strickjacken"),
        ("1206", "Jacken & Mäntel"),
    ],
    "kopf": [("86", "Hüte & Mützen")],
}


# Keyword fragments matched against the (normalised) description of a Vinted account size
# group (e.g. "Schuhe Männer", "Hosen für Herren", "Kleidergrößen") to decide which clothing
# item buckets that group's sizes apply to. Substring matching (rather than exact aliases)
# keeps this resilient to gender variants Vinted reports ("Schuhe Männer"/"Schuhe Frauen").
# Generic clothing-size groups and suit-jacket sizes are intentionally applied broadly across
# the related obenrum_* buckets: a size that turns out not to apply to a given catalog is
# silently dropped during Vinted filter resolution rather than corrupting the search.
# Keywords must be unambiguous enough to never match another bucket's size group (e.g. a
# generic gender-scoped label like "Größen Männer" or "S/M/L" can legitimately describe a
# shoe size group, so those must not appear here even though they look clothing-related).
SIZE_GROUP_KEYWORDS_BY_CLOTHING_ITEM: dict[ClothingItem, list[str]] = {
    "schuhe": ["schuhe"],
    "hosen": ["hose"],
    "kopf": ["hut", "huete", "muetze"],
    "obenrum_warm": ["hemd", "shirt", "kleidergroesse"],
    "obenrum_mittel": ["hemd", "shirt", "kleidergroesse"],
    "obenrum_kalt": ["jacke", "pullover", "kleidergroesse"],
}


def clothing_items_for_size_group(description: str) -> list[ClothingItem]:
    normalized = normalise_lookup_text(description)
    return [
        item
        for item, keywords in SIZE_GROUP_KEYWORDS_BY_CLOTHING_ITEM.items()
        if any(keyword in normalized for keyword in keywords)
    ]


def normalise_lookup_text(value: str) -> str:
    return (
        str(value)
        .strip()
        .lower()
        .replace("&", "and")
        .replace("_", " ")
        .replace("ä", "ae")
        .replace("ö", "oe")
        .replace("ü", "ue")
        .replace("ß", "ss")
    )


_FIXED_TITLE_IDS: dict[str, list[str]] = {
    normalise_lookup_text(title): [catalog_id]
    for categories in FIXED_CATEGORIES_BY_ITEM.values()
    for catalog_id, title in categories
}


def category_ids_for_alias(value: str) -> list[str]:
    normalized = normalise_lookup_text(value)
    # Fixed titles win over legacy aliases (Vinted's "Sweater" is 1811, not the 79 parent).
    direct = _FIXED_TITLE_IDS.get(normalized) or CATEGORY_ALIAS_IDS.get(normalized)
    if direct:
        return list(direct)
    # Preserve backwards compatibility with aliases that deliberately contain underscores.
    underscored = str(value).strip().lower()
    return list(CATEGORY_ALIAS_IDS.get(underscored, []))


def resolved_category_ids_for_aliases(values: list[str]) -> list[str]:
    resolved: list[str] = []
    for value in values:
        resolved.extend(category_ids_for_alias(value))
    return list(dict.fromkeys(resolved))


def default_category_filter_for_clothing_item(clothing_item: ClothingItem) -> SearchFilter:
    return SearchFilter(
        field="category",
        label="Vinted category",
        mode="include",
        values=[title for _, title in FIXED_CATEGORIES_BY_ITEM[clothing_item]],
    )


def category_options_by_clothing_item() -> dict[str, dict[str, object]]:
    options: dict[str, dict[str, object]] = {}
    for clothing_item in CLOTHING_ITEM_LABELS:
        categories = FIXED_CATEGORIES_BY_ITEM[clothing_item]
        titles = [title for _, title in categories]
        options[clothing_item] = {
            "label": CLOTHING_ITEM_LABELS[clothing_item],
            "description": CLOTHING_ITEM_DESCRIPTIONS[clothing_item],
            "default_aliases": titles,
            "allowed_aliases": titles,
            "alias_catalog_ids": {title: [catalog_id] for catalog_id, title in categories},
            "resolved_catalog_ids": [catalog_id for catalog_id, _ in categories],
        }
    return options


def _is_category_field(field: str) -> bool:
    return normalise_lookup_text(field) in _CATEGORY_FIELDS


def ensure_category_filter_for_clothing_item(
    filters: list[SearchFilter],
    clothing_item: ClothingItem | str,
) -> list[SearchFilter]:
    """Return filters with the bucket's fixed category filter in front of all other filters.

    Any stored or submitted category/catalog filter is replaced, so every search uses exactly the
    bucket's fixed Vinted catalogs.
    """
    if clothing_item not in CLOTHING_ITEM_LABELS:
        raise ValueError(f"Unsupported clothing item for Vinted categories: {clothing_item}")
    item = cast(ClothingItem, clothing_item)
    others = [filter_item for filter_item in filters if not _is_category_field(filter_item.field)]
    return [default_category_filter_for_clothing_item(item), *others]
